// Build an in-memory test claim, matching CLM0001030's known scenario
var claim = new GlideRecord('x_snc_insurance_0_claim');
claim.initialize();
claim.setValue('claim_type', 'motor');
claim.setValue('claim_amount_requested', 76000);
claim.setValue('date_of_incident', '2026-09-08');
claim.setValue('policy_number', 'POL-1001');
claim.setValue('documents_consistent', false);
claim.setValue('consistency_issues', 'Date mismatch: police_report shows 2026-09-10, but the claim says the incident was on 2026-09-08.\nAmount mismatch: the claim requests 76000, but repair_invoice total only 50000.');
claim.setValue('ai_document_findings', 'MISMATCHES:\n- Vehicle registration mismatch\nMISSING OR BLANK:\n- FIR / Report No.');
claim.setValue('documents_complete', true);

new FraudRiskScorer().evaluate(claim);

var actualScore = claim.getValue('fraud_risk_score');
var actualLevel = claim.getValue('fraud_risk_level');

// Assertion, right here in the same script
if (actualScore != 40) {
    throw new Error('Expected fraud_score 40, got ' + actualScore);
}
if (actualLevel != 'Medium') {
    throw new Error('Expected fraud_level Medium, got ' + actualLevel);
}

gs.info('PASS: Fraud score = ' + actualScore + ', Level = ' + actualLevel);
